## Copyright(c) 2017-2026 R. Mark Sharp
## This file is part of nprcgenekeepr

calcAge <- function(birth, exit) {
  if (length(birth) == 0L) {
    return(birth)
  }
  exit[is.na(exit)] <- Sys.Date()
  round((as.double(exit - birth) / 365.25), 1L)
}

